INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-001-9', 'p0110', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '二月，尚復攻譚，留蘇由、審配守鄴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-001-10', 'p0110', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，審配兄子榮夜開所守城東門內兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-001-11', 'p0110', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁氏之治也，使豪彊擅恣，親戚兼并；下民貧弱，代出租賦，衒鬻家財，不足應命；審配宗族，至乃藏匿罪人，為逋逃主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-12', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '衆數十萬，以審配、逢紀統軍事，田豐、荀諶、許攸為謀主，顏良、文醜為將率，簡精卒十萬，騎萬匹，將攻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-13', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」審配、郭圖曰：「兵書之法，十圍五攻，敵則能戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-14', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '審配、逢紀與辛評、郭圖爭權，配、紀與尚比，評、圖與譚比。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-15', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '後審配任用，與紀不睦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-16', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '尚欲分兵益譚，恐譚遂奪其衆，乃使審配守鄴，尚自將兵助譚，與太祖相拒於黎陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-17', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '漢晉春秋載審配獻書於譚曰：「春秋之義，國君死社稷，忠臣死王命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-18', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '尚使審配、蘇由守鄴，復攻譚平原。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-19', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」配厲聲曰：「汝為降虜，審配為忠臣，雖死，豈若汝生邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-006-20', 'p0110', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」　樂資山陽公載記及袁暐獻帝春秋並云太祖兵入城，審配戰於門中，旣敗，逃于井中，於井獲之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-010-21', 'p0110', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-010-22', 'p0110', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配專而無謀，逢紀果而自用，此二人留知後事，若攸家犯其法，必不能縱也，不縱，攸必為變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-010-23', 'p0110', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配以許攸家不法，收其妻子，攸怒叛紹；顏良、文醜臨陣授首；田豐以諫見誅：皆如彧所策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-010-24', 'p0110', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前日公破袁尚，禽審配，海內震駭，必人人自恐不得保其土地，守其兵衆也；今使分屬兾州，將皆動心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-011-25', 'p0110', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '太祖破鄴，籍沒審配等家財物貲以萬數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0110-a04-015-26', 'p0110', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '後尚與其兄譚爭鬬，尚出軍詣平原，留別駕審配守鄴城，孚隨尚行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-070-0', 'p0111', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '少府孔融謂彧曰：「袁紹地廣兵彊，田豐、許攸智計之士為其謀，先賢行狀：「豐字元皓，鉅鹿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-070-1', 'p0111', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」彧曰：「紹兵雖多而法不整，田豐剛而犯上，許攸貪而不正，審配專而無謀，逢紀果而自用，顏良、文醜匹夫之勇，可一戰而擒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-2', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '後袁紹至，馥從事十人棄馥去，唯恐在後，獨武、純杖刀拒，兵不能禁，紹後令田豐殺此二人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-3', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '魏郡審配，鉅鹿田豐，先賢行狀曰：「配字正南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-4', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹軍之敗也，土崩奔走，徒衆略盡，軍將皆撫膝啼泣曰：『向使田豐在此，不至於是。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-5', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐扶紹，使却入空垣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-6', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐說紹曰：「徙都之計，旣不克從，宜早圖許，奉迎天子，動託詔令，響號海內，此筭之上者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-7', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '於是簡精兵十萬，騎萬匹，欲出攻許，以審配、逢紀統軍事，田豐、荀諶及南陽許攸為謀主，顏良、文醜為將帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-8', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐說紹曰：「與公爭天下者，曹操也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-9', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐以旣失前幾，不宜便行，諫紹曰：「曹操旣破劉備，則許下非復空虛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-10', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '及軍還，或謂田豐曰：「君必見重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a03-074-11', 'p0111', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」紹還，曰：「吾不用田豐言，果為所笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-001-12', 'p0111', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '獻帝春秋曰：袁紹叛卒詣公云：「田豐使紹早襲許，若挾天子以令諸侯，四海可指麾而定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-13', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '別駕從事田豐扶紹欲郤入空垣，紹以兜鍪撲地曰：「大丈夫當前鬬死，而入牆間，豈可得活乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-14', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '衆數十萬，以審配、逢紀統軍事，田豐、荀諶、許攸為謀主，顏良、文醜為將率，簡精卒十萬，騎萬匹，將攻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-15', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳曰：紹將南師，沮授、田豐諫曰：「師出歷年，百姓疲弊，倉庾無積，賦役方殷，此國之深憂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-16', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '田豐說紹襲太祖後，紹辭以子疾，不許，豐舉杖擊地曰：「夫遭難遇之機，而以嬰兒之病失其會，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-17', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，紹之南也，田豐說紹曰：「曹公善用兵，變化無方，衆雖少，未可輕也，不如以乆持之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-18', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」紹還，謂左右曰：「吾不用田豐言，果為所笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-19', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹軍之敗也，土崩奔北，師徒略盡，軍皆拊膺而泣曰：「向令田豐在此，不至於是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-20', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」　孫盛曰：觀田豐、沮授之謀，雖良、平何以過之？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-006-21', 'p0111', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '昔項羽背范增之謀，以喪其王業；紹之殺田豐，乃甚於羽遠矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-010-22', 'p0111', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-010-23', 'p0111', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '田豐剛而犯上，許攸貪而不治。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0111-a04-010-24', 'p0111', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配以許攸家不法，收其妻子，攸怒叛紹；顏良、文醜臨陣授首；田豐以諫見誅：皆如彧所策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-0', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '馥長史耿武、別駕閔純、騎都尉沮授聞而諫曰：獻帝傳曰：「沮授，廣平人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-1', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '引沮授為別駕，因謂授曰：「今賊臣作亂，朝廷遷移。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-2', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '其冬，車駕為李傕等所追於曹陽，沮授說紹曰：「將軍累葉台輔，世濟忠義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-3', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授諫曰：「世稱萬人逐兔，一人獲之，貪者悉止，分定故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-4', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授進說曰：「近討公孫，師出歷年，百姓疲敝，倉庫無積，賦役方殷，此國之深憂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-5', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '圖等因是譖沮授曰：「授監統內外，威震三軍，若其浸盛，何以制之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-6', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授臨行，會其宗族，散資財以與之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-7', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」沮授臨舩歎曰：「上盈其志，下務其功，悠悠黃河，吾其濟乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-8', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授又說紹曰：「北兵雖衆，而勁果不及南軍；南軍穀少，而資儲不如北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-9', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授說紹可遣蔣竒別為支軍於表，以支軍為瓊等表援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a03-074-10', 'p0112', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '沮授為操軍所執，乃大呼曰：「授不降也，為所執耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-11', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳曰：沮授，廣平人，少有大志，多權略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-12', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳云：沮授說紹曰：「將軍累葉輔弼，世濟忠義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-13', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '出長子譚為青州，沮授諫紹：「必為禍始。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-14', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳曰：紹將南師，沮授、田豐諫曰：「師出歷年，百姓疲弊，倉庾無積，賦役方殷，此國之深憂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-15', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '沮授又諫紹：「良性促狹，雖驍勇不可獨任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-16', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳曰：紹臨發，沮授會其宗族，散資財以與之曰：「夫勢在則威無不加，勢亡則不保一身，哀哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-17', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝傳曰：紹將濟河，沮授諫曰：「勝負變化，不可不詳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-18', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '沮授又曰：「北兵數衆而果勁不及南，南穀虛少而貨財不及北；南利在於急戰，北利在於緩搏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-19', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '會紹遣淳于瓊等將兵萬餘人北迎運車，沮授說紹：「可遣將蔣奇別為支軍於表，以斷曹公之鈔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-20', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '沮授不及紹渡，為人所執，詣太祖，獻帝傳云：授大呼曰：「授不降也，為軍所執耳！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0112-a04-006-21', 'p0112', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」　孫盛曰：觀田豐、沮授之謀，雖良、平何以過之？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-070-0', 'p0113', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '少府孔融謂彧曰：「袁紹地廣兵彊，田豐、許攸智計之士為其謀，先賢行狀：「豐字元皓，鉅鹿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-070-1', 'p0113', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '初，紹去董卓，與許攸及紀俱詣兾州，紹以紀聦達有計策，甚信之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-070-2', 'p0113', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」彧曰：「紹兵雖多而法不整，田豐剛而犯上，許攸貪而不正，審配專而無謀，逢紀果而自用，顏良、文醜匹夫之勇，可一戰而擒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-074-3', 'p0113', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '初，紹去董卓，與許攸及紀俱詣兾州，以紀聦達有計策，甚親信之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-074-4', 'p0113', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '於是簡精兵十萬，騎萬匹，欲出攻許，以審配、逢紀統軍事，田豐、荀諶及南陽許攸為謀主，顏良、文醜為將帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-074-5', 'p0113', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '許攸進曰：「曹操兵少而悉師拒我，許下餘守埶必空弱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a03-074-6', 'p0113', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '曹瞞傳曰：「公聞許攸來，跣出迎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-001-7', 'p0113', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '頃之，兾州刺史王芬、南陽許攸、沛國周旌等連結豪傑，謀廢靈帝，立合肥侯，以告太祖，太祖拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-001-8', 'p0113', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '羽鑿齒漢晉春秋曰：許攸說紹曰：「公無與操相攻也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-001-9', 'p0113', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '紹謀臣許攸貪財，紹不能足，來奔，因說公擊瓊等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-001-10', 'p0113', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '許攸曰：「明且鑒於鏡，此益不忘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-006-11', 'p0113', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '衆數十萬，以審配、逢紀統軍事，田豐、荀諶、許攸為謀主，顏良、文醜為將率，簡精卒十萬，騎萬匹，將攻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-006-12', 'p0113', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，紹去董卓出奔，與許攸及紀俱詣兾州，紹以紀聦達有計策，甚親信之，與共舉事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-010-13', 'p0113', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-010-14', 'p0113', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '田豐剛而犯上，許攸貪而不治。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-010-15', 'p0113', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配以許攸家不法，收其妻子，攸怒叛紹；顏良、文醜臨陣授首；田豐以諫見誅：皆如彧所策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-010-16', 'p0113', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會許攸來降，言紹遣淳于瓊等將萬餘兵迎運糧，將驕卒惰，可要擊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-012-17', 'p0113', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '南陽許攸、魏略曰：攸字子遠，少與袁紹及太祖善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-023-18', 'p0113', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '時將軍許攸擁部曲，不附太祖而有慢言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-023-19', 'p0113', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '」太祖曰：「許攸慢吾，如何可置乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-023-20', 'p0113', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '」襲曰：「殿下謂許攸何如人邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0113-a04-023-21', 'p0113', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '臣聞千鈞之弩不為鼷鼠發機，萬石之鍾不以莛撞起音，今區區之許攸，何足以勞神武哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-008-full-0', 'p0114', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '扶風人馬騰、漢陽人王國並叛，寇三輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-008-1', 'p0114', 'houhanshu', 'a03-008', '《後漢書·卷八》', '扶風人馬騰、漢陽人王國並叛，寇三輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-009-2', 'p0114', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，韓遂、馬騰與郭汜、樊稠戰於長平觀，遂、騰敗績，左中郎將劉範、前益州刺史种劭戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-009-3', 'p0114', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」袁宏紀曰：「是時馬騰以李傕等專亂，以益州刺史劉焉宗室大臣，遣使招引共誅傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-009-4', 'p0114', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十七年夏五月癸未，誅衞尉馬騰，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-056-5', 'p0114', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '」遂與馬騰、韓遂及左中郎劉範、諫議大夫馬宇共攻李傕、郭汜，以報其仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-072-6', 'p0114', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '而鄙司馬扶風馬騰，典略曰：「騰字壽成，扶風茂陵人，馬援後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-072-7', 'p0114', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初，卓之入關，要韓遂、馬騰共謀山東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-072-8', 'p0114', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '興平元年，馬騰從隴右來朝，進屯霸橋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-072-9', 'p0114', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '韓遂與馬騰自還涼州，更相戰爭，乃下隴據關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-072-10', 'p0114', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '復徵馬騰為衞尉，封槐里侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a03-075-11', 'p0114', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '興平元年，征西將軍馬騰與範謀誅李傕，焉遣叟兵五千助之，漢世謂蜀為叟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-001-12', 'p0114', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '騎士皆下馬，付麥以相付，於是太祖馬騰入麥中，勑主簿議罪；主簿對以春秋之義，罰不加於尊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-006-13', 'p0114', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '是歲，韓遂、馬騰等降，率衆詣長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-006-14', 'p0114', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '九州春秋曰：馬騰、韓遂之敗，樊稠追至陳倉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-010-15', 'p0114', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖渡河，擊紹子譚、尚，而高幹、郭援侵略河東，關右震動，鍾繇帥馬騰等擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-013-16', 'p0114', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時關中諸將馬騰、韓遂等，各擁彊兵相與爭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-013-17', 'p0114', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」張旣說馬騰會擊援，騰遣子超將精兵逆之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-013-18', 'p0114', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '濟水未半，擊，大破之，司馬彪戰略曰：袁尚遣高幹、郭援將兵數萬人，與匈奴單于寇河東，遣使與馬騰、韓遂等連和，騰等陰許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-015-19', 'p0114', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '司隷校尉鍾繇遣旣說將軍馬騰等，旣為言利害，騰等從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-015-20', 'p0114', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖以旣為議郎，參繇軍事，使西徵諸將馬騰等，皆引兵會擊晟等，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-015-21', 'p0114', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '建安初，約與馬騰相攻擊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-018-22', 'p0114', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '初平中，從馬騰擊反羌叛氐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-031-23', 'p0114', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '時征西將軍馬騰屯郿而反，焉及範與騰通謀，引兵襲長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-031-24', 'p0114', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '英雄記曰：範從長安亡之馬騰營，從焉求兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0114-a04-038-25', 'p0114', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '初，韓遂與馬騰作亂關中，數與璋父焉交通信，至騰子超復與璋相聞，有連蜀之意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-008-full-0', 'p0115', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '湟中義從胡北宮伯玉與先零羌叛，以金城人邊章、韓遂為軍帥，攻殺護羌校尉伶徵、金城太守陳懿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-008-full-1', 'p0115', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '夏四月，涼州刺史耿鄙討金城賊韓遂，鄙兵大敗，遂寇漢陽，漢陽太守傅燮戰沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-008-2', 'p0115', 'houhanshu', 'a03-008', '《後漢書·卷八》', '湟中義從胡北宮伯玉與先零羌叛，以金城人邊章、韓遂為軍帥，攻殺護羌校尉伶徵、金城太守陳懿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-008-3', 'p0115', 'houhanshu', 'a03-008', '《後漢書·卷八》', '夏四月，涼州刺史耿鄙討金城賊韓遂，鄙兵大敗，遂寇漢陽，漢陽太守傅燮戰沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-009-4', 'p0115', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，韓遂、馬騰與郭汜、樊稠戰於長平觀，遂、騰敗績，左中郎將劉範、前益州刺史种劭戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-009-5', 'p0115', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十六年秋九月庚戌，曹操與韓遂、馬超戰於渭南，遂等大敗，關西平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-048-6', 'p0115', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '中平二年，漢陽賊邊章、韓遂與羌胡為寇，東侵三輔，時遣車騎將軍皇甫嵩西討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-056-7', 'p0115', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '」遂與馬騰、韓遂及左中郎劉範、諫議大夫馬宇共攻李傕、郭汜，以報其仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-058-8', 'p0115', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '會西羌反，邊章、韓遂作亂隴右，徵發天下，役賦無已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-058-9', 'p0115', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '中平四年，鄙率六郡兵討金城賊王國、韓遂等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-069-10', 'p0115', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '碩雖擅兵於中，而猶畏忌於進，乃與諸常侍共說帝遣進西擊邊章、韓遂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-071-11', 'p0115', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '會邊章、韓遂作亂隴右，明年春，詔嵩迴鎮長安，以衞園陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-071-12', 'p0115', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '獻帝春秋曰：「初卓為前將軍，嵩為左將軍，俱征邊章、韓遂，爭雄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-13', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '伯玉等乃劫致金城人邊章、韓遂，獻帝春秋曰：「涼州義從宋建、王國等反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-14', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '嵩以無功免歸，而邊章、韓遂等大盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-15', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '其冬，徵溫還京師，韓遂乃殺邊章及伯玉、文侯，擁兵十餘萬，進圍隴西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-16', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」亦擁兵反叛，又漢陽王國，自號「合衆將軍」，皆與韓遂合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-17', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '韓遂等復共廢王國，而劫故信都令漢陽閻忠，英雄記曰：「王國等起兵，劫忠為主，統三十六部，號『車騎將軍』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-18', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初，卓之入關，要韓遂、馬騰共謀山東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-19', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '韓遂聞之，乃率衆來欲和騰、傕，旣而復與騰合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-20', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '韓遂使人語稠曰：「天下反覆未可知，相與州里，今雖小違，要當大同，欲共一言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-21', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '韓遂與馬騰自還涼州，更相戰爭，乃下隴據關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-22', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '十六年，超與韓遂舉關中背曹操，操擊破之，遂、超敗走，騰坐夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-072-23', 'p0115', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」韓遂走金城羌中，為其帳下所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-075-24', 'p0115', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '韓遂、馬超之亂，關西民奔魯者數萬家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-102-25', 'p0115', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '是時益州牧劉璋據益州，漢中太守張魯別據漢中，韓遂據涼州，宗建別據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a03-102-26', 'p0115', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '十九年，獲宗建；韓遂逃于羌中，病死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-27', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」金城邊章、韓遂殺刺史郡守以叛，衆十餘萬，天下騷動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-28', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是時關中諸將疑繇欲自襲，馬超遂與韓遂、楊秋、李堪、成宜等叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-29', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓遂請與公相見，公與遂父同歲孝廉，又與遂同時儕輩，於是交馬語移時，不及軍事，但說京都舊故，拊手歡笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-30', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓遂徙金城，入氐王千萬部，率羌、胡萬餘騎與夏侯淵戰，擊，大破之，遂走西平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-31', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '西平、金城諸將麴演、蔣石等共斬送韓遂首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-001-32', 'p0115', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '韓遂、宋建，南結巴、蜀，羣逆合從，圖危社稷，君復命將，龍驤虎奮，梟其元首，屠其窟栖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-006-33', 'p0115', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '韓遂等起涼州，復為中郎將，西拒遂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-006-34', 'p0115', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '山陽公載記曰：初卓為前將軍，皇甫嵩為左將軍，俱征韓遂，各不相下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-006-35', 'p0115', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '是歲，韓遂、馬騰等降，率衆詣長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-006-36', 'p0115', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '九州春秋曰：馬騰、韓遂之敗，樊稠追至陳倉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-006-37', 'p0115', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '傕以是疑稠與韓遂私和而有異意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-008-38', 'p0115', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '遷幽州刺史，徵拜議郎，參車騎將軍張溫軍事，西討韓遂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-008-39', 'p0115', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '後邊章、韓遂為亂，司空張溫銜命征討；又請謙為參軍事，接遇甚厚，而謙輕其行事，心懷不服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-008-40', 'p0115', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '邊章、韓遂為亂涼州，金城麴勝襲殺祖厲長劉儁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-008-41', 'p0115', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '韓遂、馬超之亂，關西民從子午谷奔之者數萬家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-009-42', 'p0115', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '從征韓遂等，戰於渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-009-43', 'p0115', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '韓遂在顯親，淵欲襲取之，遂走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-010-44', 'p0115', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」彧曰：「關中將帥以十數，莫能相一，唯韓遂、馬超最彊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-010-45', 'p0115', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖後與韓遂、馬超戰於渭南，超等索割地以和，并求任子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-013-46', 'p0115', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '時關中諸將馬騰、韓遂等，各擁彊兵相與爭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-013-47', 'p0115', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '濟水未半，擊，大破之，司馬彪戰略曰：袁尚遣高幹、郭援將兵數萬人，與匈奴單于寇河東，遣使與馬騰、韓遂等連和，騰等陰許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-015-48', 'p0115', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '典略曰：韓遂在湟中，其壻閻行欲殺遂以降，夜攻遂，不下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-016-49', 'p0115', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '」旣荅曰：「金城郡，昔為韓遂所見屠剥，死喪流亡，或竄戎狄，或陷寇亂，戶不滿五百。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-016-50', 'p0115', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '韓遂、馬超之叛也，弘農、馮翊多舉縣邑以應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-017-51', 'p0115', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從破馬超、韓遂於渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-017-52', 'p0115', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '韓遂、馬超等反關右，遣晃屯汾陰以撫河東，賜牛酒，令上先人墓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-018-53', 'p0115', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從討韓遂、馬超於潼關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-018-54', 'p0115', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '至十五年，將軍韓遂自上討猛，猛發兵遣軍東拒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-021-55', 'p0115', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又典略載太祖初征荊州，使瑀作書與劉備，及征馬超，又使瑀作書與韓遂，此二書今具存。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-021-56', 'p0115', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太祖嘗使瑀作書與韓遂，時太祖適近出，瑀隨從，因於馬上具草，書成呈之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-023-57', 'p0115', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖徙出故韓遂、馬超等兵五千餘人，使平難將軍殷署等督領，以儼為關中護軍，盡統諸軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-024-58', 'p0115', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '太祖欲遣鍾繇等討張魯，柔諫，以為今猥遣大兵，西有韓遂、馬超，謂為己舉，將相扇動作逆，宜先招集三輔，三輔苟平，漢中可傳檄而定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-030-59', 'p0115', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '建安中，公孫康分屯有縣以南荒地為帶方郡，遣公孫模、張敞等收集遺民，興兵伐韓濊，舊民稍出，是後倭韓遂屬帶方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-60', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '父騰，靈帝末與邊章、韓遂等俱起事於西州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-61', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '後騰與韓遂不和，求還京畿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-62', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '會三輔亂，不復來東，而與鎮西將軍韓遂結為異姓兄弟，始甚相親，後轉以部曲相侵入，更為讎敵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-63', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '超旣統衆，遂與韓遂合從，及楊秋、李堪、成宜等相結，進軍至潼關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-64', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '山陽公載記曰：初，曹公軍在蒲阪，欲西渡，超謂韓遂曰：「宜於渭北拒之，不過二十日，河東穀盡，彼必走矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-036-65', 'p0115', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '典略曰：建安十六年，超與關中諸將侯選、程銀、李堪、張橫、梁興、成宜、馬玩、楊秋、韓遂等，凡十部，俱反，其衆十萬，同據河、潼，建列營陣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-038-66', 'p0115', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '初，韓遂與馬騰作亂關中，數與璋父焉交通信，至騰子超復與璋相聞，有連蜀之意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-042-67', 'p0115', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '是時，劉璋據益州，張魯據漢中，韓遂據涼州，宋建據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-042-68', 'p0115', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '十九年，獲宋建，韓遂逃于羌中，被殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0115-a04-054-69', 'p0115', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '今北土旣未平安，加馬超、韓遂尚在關西，為操後患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-009-0', 'p0116', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」袁宏紀曰：「是時馬騰以李傕等專亂，以益州刺史劉焉宗室大臣，遣使招引共誅傕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-031-1', 'p0116', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '曾孫商，益州牧劉焉以為蜀郡太守，有治聲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-075-2', 'p0116', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '劉焉字君郎，江夏竟陵人也，竟陵今復州縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-075-3', 'p0116', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '論曰：劉焉覩時方艱，先求後亡之所，左傳曰，鄭公孫黑肱有疾，歸邑于公，曰：「吾聞之，生於亂代，貴而能貧，人無求焉，可以後亡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-079-4', 'p0116', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '州牧劉焉表薦之，時王塗隔塞，詔命竟不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-104-5', 'p0116', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '臣昭案：劉焉傳，興平元年，天火燒其城府輜重，延及民家，館邑無餘也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a03-118-6', 'p0116', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '至孝靈在位，橫流旣及，劉焉徼偽，自為身謀，非有憂國之心，專懷狼據之策，抗論昏世，薦議愚主，盛稱宜重牧伯，謂足鎮壓萬里，挾姦樹筭，苟罔一時，豈可永為國本，長期勝術哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-008-7', 'p0116', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '英雄記曰：虞讓太尉，因薦衞尉趙謨、益州牧劉焉、豫州牧黃琬、南陽太守羊續，並任為公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-008-8', 'p0116', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '益州牧劉焉以魯為督義司馬，與別部司馬張脩將兵擊漢中太守蘇固，魯遂襲脩殺之，奪其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-031-9', 'p0116', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '劉焉字君郎，江夏竟陵人也，漢魯恭王之後裔，章帝元和中徙封竟陵，支庶家焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-031-10', 'p0116', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '出為監軍使者，領益州牧，封陽城侯，當收儉治罪；續漢書曰：是時用劉虞為幽州，劉焉為益州，劉表為荊州，賈琮為兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-031-11', 'p0116', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '英雄記曰：劉焉起兵，不與天下討董卓，保州自守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-031-12', 'p0116', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '而劉焉聞董扶之辭則心存益土，聽相者之言則求婚吳氏，遽造輿服，圖竊神器，其惑甚矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-034-13', 'p0116', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '兄吳壹，少孤，壹父素與劉焉有舊，是以舉家隨焉入蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-038-14', 'p0116', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '奏記州牧劉焉，薦儒士任定祖曰：「昔百里、蹇叔以耆艾而定策，甘羅、子奇以童冠而立功，故書美黃髮，而易稱顏淵，固知選士用能，不拘長幼，明矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-038-15', 'p0116', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '州牧劉焉表薦安味精道度，厲節高邈，揆其器量，國之元寶，宜處弼疑之輔，以消非常之咎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-039-16', 'p0116', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '臣松之案：劉焉在漢靈帝時已經宗正太常，出為益州牧，祥始以孫堅作長沙時為江夏太守，不得舉焉為孝廉，明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-039-17', 'p0116', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '父常，送故將軍劉焉入蜀，值王路隔塞，遂不得還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0116-a04-042-18', 'p0116', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '獻帝遷都長安，遂逃入蜀，劉焉父子待以客禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a03-072-0', 'p0117', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '旣奔漢中，聞備圍劉璋於成都，密書請降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a03-075-1', 'p0117', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '劉璋遣詣曹公，公不甚禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a03-102-2', 'p0117', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '是時益州牧劉璋據益州，漢中太守張魯別據漢中，韓遂據涼州，宗建別據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a03-113-3', 'p0117', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '建安六年，劉璋分巴，以永寧為巴東郡，以墊江為巴西郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-001-4', 'p0117', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '益州牧劉璋始受徵役，遣兵給軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-001-5', 'p0117', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備襲劉璋，取益州，遂據巴中；遣張郃擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-021-6', 'p0117', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '益州牧劉璋與表有隙，覬以治書侍御史使益州，令璋下兵以綴表軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-031-7', 'p0117', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '張璠曰：劉璋愚弱而守善言，斯亦宋襄公、徐偃王之徒，未為無道之主也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-032-8', 'p0117', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備欲自圖蜀，拒荅不聽，曰：「益州民富彊，土地險阻，劉璋雖弱，足以自守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-032-9', 'p0117', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '十六年，益州牧劉璋遙聞曹公將遣鍾繇等向漢中討張魯，內懷恐懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-032-10', 'p0117', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '劉璋遣詣曹公，曹公不甚禮松；主簿楊脩深器之，白公辟松，公不納。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-032-11', 'p0117', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '十九年夏，雒城破，益部耆舊雜記曰：劉璋遣張任與劉璝率精兵拒捍先主於涪，為先主所破，退與璋子循守雒城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-032-12', 'p0117', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '獻帝之初，三輔飢亂，堅去官，與弟援南入蜀依劉璋，璋以堅為長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-035-13', 'p0117', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉璋闇弱，張魯在北，民殷國富而不知存卹，智能之士思得明君。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-035-14', 'p0117', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '建安十六年，益州牧劉璋遣法正迎先主，使擊張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-035-15', 'p0117', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉璋闇弱，自焉已來有累世之恩，文法羈縻，互相承奉，德政不舉，威刑不肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-036-16', 'p0117', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主入益州，還攻劉璋，飛與諸葛亮等泝流而上，分定郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-036-17', 'p0117', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '魯不足與計事，內懷於邑，聞先主圍劉璋於成都，密書請降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-036-18', 'p0117', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '自葭萌受任，還攻劉璋，忠常先登陷陣，勇毅冠三軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-036-19', 'p0117', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主自葭萌還攻劉璋，召諸葛亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-037-20', 'p0117', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '益州牧劉璋與先主會涪，統進策曰：「今因此會，便可執之，則將軍無用兵之勞，而坐定一州也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-037-21', 'p0117', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '臣松之以為謀襲劉璋，計雖出於統，然違義成功，本由詭道，心旣內疚，則歡情自戢，故聞備稱樂之言，不覺率爾而對也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-037-22', 'p0117', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '建安初，天下饑荒，正與同郡孟達俱入蜀依劉璋，乆之為新都令，後召署軍議校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-038-23', 'p0117', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後劉璋遂使使招靖，靖來入蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-038-24', 'p0117', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主入益州，劉璋見雍，甚愛之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-038-25', 'p0117', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '劉璋時，宓同郡王商為治中從事，與宓書曰：「貧賤困苦，亦何時可以終身！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-039-26', 'p0117', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '漢末，和率宗族西遷，益州牧劉璋以為牛鞞、音髀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-039-27', 'p0117', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」主簿請自送至州，見益州牧劉璋，璋父焉昔為巴父祥所舉孝廉，見巴驚喜，每大事輒以咨訪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-039-28', 'p0117', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」初攻劉璋，備與士衆約：「若事定，府庫百物，孤無預焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-040-29', 'p0117', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '及先主入蜀，自葭萌還攻劉璋，時封年二十餘，有武藝，氣力過人，將兵俱與諸葛亮、張飛等泝流西上，所在戰克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-040-30', 'p0117', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '初，劉璋遣扶風孟達副法正，各將兵二千人，使迎先主，先主因令達并領其衆，留屯江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-040-31', 'p0117', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '羕仕州，不過書佐，後又為衆人所謗毀於州牧劉璋，璋髠鉗羕為徒隷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-040-32', 'p0117', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '曹公入荊州時，嚴宰秭歸，遂西詣蜀，劉璋以為成都令，復有能名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-041-33', 'p0117', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主自葭萌南還襲劉璋，留峻守葭萌城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-041-34', 'p0117', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '劉璋時入蜀，為梓潼令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-041-35', 'p0117', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '劉璋時，舉孝廉，為魚復長，還州署從事，領帳下司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-041-36', 'p0117', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '劉璋時為緜竹令，先主攻緜竹時，詩先舉城降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-042-37', 'p0117', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '劉璋辟為從事，以疾去官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-042-38', 'p0117', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '州牧劉璋，辟以為師友從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-042-39', 'p0117', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '是時，劉璋據益州，張魯據漢中，韓遂據涼州，宋建據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-042-40', 'p0117', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '初，先主與劉璋會涪時，裕為璋從事，侍坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-042-41', 'p0117', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '漢末大亂，敏隨姊奔荊州，姊夫黃琬是劉璋祖母之姪，故璋遣迎琬妻，敏遂俱與姊入蜀，常為璋賔客。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-043-42', 'p0117', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '少為郡吏，州牧劉璋召為主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-043-43', 'p0117', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '及先主襲取益州，將帥分下郡縣，郡縣望風景附，權閉城堅守，須劉璋稽服，乃詣降先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-043-44', 'p0117', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '後貢恢於州，涉道未至，聞先主自葭萌還攻劉璋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-044-45', 'p0117', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '伯仁姑，益州牧劉璋之母也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-045-46', 'p0117', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '劉璋母，觀之族姑，璋又以女妻觀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-045-47', 'p0117', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '劉璋時，為巴郡太守，還為州治中從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-045-48', 'p0117', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '劉璋時，為中郎將，將兵拒先主於涪，詣降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-045-49', 'p0117', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '華陽國志曰：邵兄邈，字漢南，劉璋時為牛鞞長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-045-50', 'p0117', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '勳，劉璋時為州書佐，先主定蜀，辟為左將軍屬，後轉州別駕從事，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-046-51', 'p0117', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：策被詔勑，與司空曹公、衞將軍董承、益州牧劉璋等并力討袁術、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-054-52', 'p0117', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是時劉璋為益州牧，外有張魯寇侵，瑜乃詣京見權曰：「今曹操新折衂，方憂在腹心，未能與將軍道兵相事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a04-054-53', 'p0117', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '先是，益州牧劉璋綱維頹弛，周瑜、甘寧並勸權取蜀，權以咨備，備內欲自規，乃偽報曰：「備與璋託為宗室，兾憑英靈，以匡漢朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a05-001-54', 'p0117', 'jinshu', 'a05-001', '《晉書·卷一》', '從討張魯，言於魏武曰：「劉備以詐力虜劉璋，蜀人未附而遠爭江陵，此機不可失也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a05-014-55', 'p0117', 'jinshu', 'a05-014', '《晉書·卷十四》', '建安六年，劉璋改永寧為巴東郡，分巴郡墊江置巴西郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0117-a05-014-56', 'p0117', 'jinshu', 'a05-014', '《晉書·卷十四》', '獻帝初平元年，劉璋分巴郡立永寧郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-009-0', 'p0118', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月，曹操破漢中，張魯降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-072-1', 'p0118', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '阜與戰，身被五創，宗族昆季死者七人，超遂南奔張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-075-2', 'p0118', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '沛人張魯，母有恣色，兼挾鬼道，往來焉家，遂任魯以為督義司馬，遂與別部司馬張脩將兵掩殺漢中太守蘇固，斷絕斜谷，殺使者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-075-3', 'p0118', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '張魯以璋闇懦，不復承順。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-075-4', 'p0118', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '十六年，璋聞曹操當遣兵向漢中討張魯，內懷恐懼，松復說璋迎劉備以拒操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-075-5', 'p0118', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '明年，曹操破張魯，定漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a03-102-6', 'p0118', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '是時益州牧劉璋據益州，漢中太守張魯別據漢中，韓遂據涼州，宗建別據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-001-7', 'p0118', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張魯據漢中，三月，遣鍾繇討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-001-8', 'p0118', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，公西征張魯，至陳倉，將自武都入氐；氐人塞道，先遣張郃、朱靈等攻破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-001-9', 'p0118', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張魯使弟衞與將楊昂等據陽平關，橫山築城十餘里，攻之不能拔，乃引軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-002-10', 'p0118', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '』臣以合辭語鎮南將軍張魯，魯亦問合知書所出？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-006-11', 'p0118', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '趙衢等舉義兵討超，超走漢中從張魯，後奔劉備，死於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-008-12', 'p0118', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張魯字公祺，沛國豐人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-008-13', 'p0118', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '魏名臣奏載董昭表曰：「武皇帝承涼州從事及武都降人之辭，說張魯易攻，陽平城下南北山相遠，不可守也，信以為然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-008-14', 'p0118', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '」又楊曁表曰：「武皇帝始征張魯，以十萬之衆，身親臨履，指授方略，因就民麥以為軍糧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-008-15', 'p0118', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '臣松之以為張魯雖有善心，要為敗而後降，今乃寵以萬戶，五子皆封侯，過矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-009-16', 'p0118', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖西征張魯，淵等將涼州諸將侯王已下，與太祖會休亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-009-17', 'p0118', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '張魯前為鎮北將軍，休為司馬，家南鄭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-009-18', 'p0118', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '時漢中有甘露降，子朗見張魯精兵數萬人，有四塞之固，遂建言赤氣乆衰，黃家當興，欲魯舉號，魯不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-010-19', 'p0118', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '魏武後克平張魯，蜀中一日數十驚，劉備雖斬之而不能止，由不用劉曄之計，以失席卷之會，斤石旣差，悔無所及，即亦此事之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-014-20', 'p0118', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖征張魯，轉曄為主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-014-21', 'p0118', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '資曰：「昔武皇帝征南鄭，取張魯，陽平之役，危而後濟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-015-22', 'p0118', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '」從征張魯，別從散關入討叛氐，收其麥以給軍食。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-016-23', 'p0118', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '太祖征張魯，過其郡，見則恱之，使為軍導。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-017-24', 'p0118', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖征張魯，教與護軍薛悌，署函邊曰「賊至乃發」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-017-25', 'p0118', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖征張魯，先遣郃督諸軍討興和氐王竇茂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-018-26', 'p0118', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '後復隨超奔漢中，從張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-021-27', 'p0118', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '司隷校尉鍾繇求以三千兵入關，外託討張魯，內以脅取質任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-021-28', 'p0118', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '若以兵入關中，當討張魯，魯在深山，道徑不通，彼必疑之；一相驚動，地險衆彊，殆難為慮！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-022-29', 'p0118', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '羣以為「太祖昔到陽平攻張魯，多收豆麥以益軍糧，魯未下而食猶乏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-023-30', 'p0118', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖克張魯，洽陳便宜以時拔軍徙民，可省置守之費。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-023-31', 'p0118', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '」後襲領丞相長史，隨太祖到漢中討張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-024-32', 'p0118', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '太祖欲遣鍾繇等討張魯，柔諫，以為今猥遣大兵，西有韓遂、馬超，謂為己舉，將相扇動作逆，宜先招集三輔，三輔苟平，漢中可傳檄而定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-025-33', 'p0118', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '超盡兼隴右之衆，而張魯又遣大將楊昂以助之，凡萬餘人，攻城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-025-34', 'p0118', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '」遂共閉門逐超，超奔漢中，從張魯得兵還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-031-35', 'p0118', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '張魯母始以鬼道，又有少容，常往來焉家，故焉遣魯為督義司馬，住漢中，斷絕谷閣，殺害漢使。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-031-36', 'p0118', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '璋，字季玉，旣襲焉位，而張魯稍驕恣，不承順璋，璋殺魯母及弟，遂為讎敵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-031-37', 'p0118', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '璋資給先主，使討張魯，然後分別。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-38', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '獻帝春秋曰：孫權欲與備共取蜀，遣使報備曰：「米賊張魯居王巴、漢，為曹操耳目，規圖益州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-39', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '今欲先攻取璋，進討張魯，首尾相連，一統吳、楚，雖有十操，無所憂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-40', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '張魯虛偽，未必盡忠於操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-41', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '十六年，益州牧劉璋遙聞曹公將遣鍾繇等向漢中討張魯，內懷恐懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-42', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '別駕從事蜀郡張松說璋曰：「曹公兵彊無敵於天下，若因張魯之資以取蜀土，誰能禦之者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-43', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '璋增先主兵，使擊張魯，又令督白水軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-44', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是歲，曹公定漢中，張魯遁走巴西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-032-45', 'p0118', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '遣黃權將兵迎張魯，張魯已降曹公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-033-46', 'p0118', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '簡喜，以語張魯，魯為洗沐送詣益州，備乃立以為太子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-035-47', 'p0118', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉璋闇弱，張魯在北，民殷國富而不知存卹，智能之士思得明君。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-035-48', 'p0118', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '建安十六年，益州牧劉璋遣法正迎先主，使擊張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-036-49', 'p0118', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公破張魯，留夏侯淵、張郃守漢川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-036-50', 'p0118', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '進退狼狽，乃奔漢中依張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-036-51', 'p0118', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '後奔漢中，張魯以為都講祭酒，欲妻之以女，或諫魯曰：「有人若此不愛其親，焉能愛人？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-036-52', 'p0118', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '典略曰：初超之入蜀，其庶妻董及子秋，留依張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-037-53', 'p0118', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '後因璋聞曹公欲遣將征張魯之有懼心也，松遂說璋宜迎先主，使之討魯，復令正銜命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-037-54', 'p0118', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '二十二年，正說先主曰：「曹操一舉而降張魯，定漢中，不因此勢以圖巴、蜀，而留夏侯淵、張郃屯守，身遽北還，此非其智不逮而力不足也，必將內有憂偪故耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-039-55', 'p0118', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」旣入，巴復諫曰：「若使備討張魯，是放虎於山林也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-040-56', 'p0118', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '初在西平、上庸間聚衆數千家，後與張魯通，又遣使詣曹公，曹公加其號為將軍，因使領上庸都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-041-57', 'p0118', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '張魯遣將楊帛誘峻，求共守城，峻曰：「小人頭可得，城不可得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-042-58', 'p0118', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '是時，劉璋據益州，張魯據漢中，韓遂據涼州，宋建據枹罕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-042-59', 'p0118', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '二十年秋，曹公攻漢中，張魯降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-043-60', 'p0118', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '時別駕張松建議，宜迎先主，使伐張魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-043-61', 'p0118', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '及曹公破張魯，魯走入巴中，權進曰：「若失漢中，則三巴不振，此為割蜀之股臂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-052-62', 'p0118', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '昔竇融歸漢，與國升降；張魯降魏，賞延于世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-054-63', 'p0118', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是時劉璋為益州牧，外有張魯寇侵，瑜乃詣京見權曰：「今曹操新折衂，方憂在腹心，未能與將軍道兵相事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-054-64', 'p0118', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '乞與奮威俱進取蜀，得蜀而并張魯，因留奮威固守其地，好與馬超結援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a04-060-65', 'p0118', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '吳書曰：建安十六年，岱督郎將尹異等，以兵二千人西誘漢中賊帥張魯到漢興寋城，魯嫌疑斷道，事計不立，權遂召岱還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0118-a05-001-66', 'p0118', 'jinshu', 'a05-001', '《晉書·卷一》', '從討張魯，言於魏武曰：「劉備以詐力虜劉璋，蜀人未附而遠爭江陵，此機不可失也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-0', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '中平元年春二月，鉅鹿人張角自稱「黃天」，其部師有三十六萬，皆著黃巾，同日反叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-1', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-2', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '盧植破黃巾，圍張角於廣宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-3', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '植連破張角，垂當拔之，小黃門左豐言於帝曰：「盧中郎固壘息軍，以待天誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-4', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣中郎將董卓攻張角，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-5', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '乙巳，詔皇甫嵩北討張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-6', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '冬十月，皇甫嵩與黃巾賊戰於廣宗，獲張角弟梁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-full-7', 'p0119', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十一月，皇甫嵩又破黃巾于下曲陽，斬張角弟寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-8', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '中平元年春二月，鉅鹿人張角自稱「黃天」，其部師有三十六萬，皆著黃巾，同日反叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-9', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-10', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '盧植破黃巾，圍張角於廣宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-11', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '植連破張角，垂當拔之，小黃門左豐言於帝曰：「盧中郎固壘息軍，以待天誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-12', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣中郎將董卓攻張角，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-13', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '乙巳，詔皇甫嵩北討張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-14', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '冬十月，皇甫嵩與黃巾賊戰於廣宗，獲張角弟梁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-008-15', 'p0119', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十一月，皇甫嵩又破黃巾于下曲陽，斬張角弟寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-054-16', 'p0119', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '先是黃巾帥張角等執左道，稱大賢，以誑燿百姓，天下繈負歸之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-054-17', 'p0119', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '賜時在司徒，召掾劉陶告曰：「張角等遭赦不悔，而稍益滋蔓，今若下州郡捕討，恐更騷擾，速成其患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-054-18', 'p0119', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '後帝徙南宮，閱錄故事，得賜所上張角奏及前侍講注籍，所注之籍錄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-057-19', 'p0119', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '時鉅鹿張角偽託大道，妖惑小民，陶與奉車都尉樂松、議郎袁貢連名上疏言之，曰：「聖王以天下耳目為視聽，故能無不聞見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-057-20', 'p0119', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '明年，張角反亂，海內鼎沸，帝思陶言，封中陵鄉侯，三遷尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-057-21', 'p0119', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '竊見天下前遇張角之亂，後遭邊章之寇，每聞羽書告急之聲，心灼內熱，四體驚竦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-057-22', 'p0119', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '宦官事急，共讒陶曰：「前張角事發，詔書示以威恩，自此以來，各各改悔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-058-23', 'p0119', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '後為護軍司馬，與左中郎將皇甫嵩俱討賊張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-058-24', 'p0119', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '今張角起於趙、魏，黃巾亂於六州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-058-25', 'p0119', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '誠使張角梟夷，黃巾變服，臣之所憂，甫益深耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-058-26', 'p0119', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '及破張角，爕功多當封，續漢書曰：「爕軍斬賊三帥卜巳、張伯、梁仲寧等，功高為封首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-063-27', 'p0119', 'houhanshu', 'a03-063', '《後漢書·卷六十三》', '先是安平王續為張角賊所略，國家贖王得還，朝廷議復其國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-064-28', 'p0119', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '連戰破賊帥張角，斬獲萬餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-067-29', 'p0119', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '若乆不赦宥，輕與張角合謀，為變滋大，悔之無救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-069-30', 'p0119', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '中平元年，黃巾賊張角等起，以進為大將軍，率左右羽林五營士屯都亭，修理器械，以鎮京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-069-31', 'p0119', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '張角別黨馬元義謀起洛陽，進發其姦，以功封慎侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-071-32', 'p0119', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '初，鉅鹿張角自稱「大賢良師」，「良」或作「郎」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-071-33', 'p0119', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '未及作亂，而張角弟子濟南唐周上書告之，於是車裂元義於洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-071-34', 'p0119', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '時北中郎將盧植及東中郎將董卓討張角，並無功而還，乃詔嵩進兵討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-071-35', 'p0119', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '初，嵩討張角，路由鄴，見中常侍趙忠舍宅踰制，乃奏沒入之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-071-36', 'p0119', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」稱「時人說皇甫嵩之不伐，汝豫之戰，歸功朱儁，張角之捷，本之於盧植，收名斂策，斂策，不論其功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-072-37', 'p0119', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '中平元年，拜東中郎將，持節，代盧植擊張角於下曲陽，軍敗抵罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-075-38', 'p0119', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '光和中，東方有張角，漢中有張脩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-078-39', 'p0119', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '黃巾旣作，盜賊糜沸，郎中中山張鈞上書曰：「竊惟張角所以能興兵作亂，萬人所以樂附之者，其源皆由十常侍多放父兄、子弟、婚親、賔客典據州郡，辜榷財利，侵掠百姓，百姓之冤無所告訴，故謀議不軌，聚為盜賊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-078-40', 'p0119', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '詔使廷尉、侍御史考為張角道者，御史承讓等旨，遂誣奏鈞學黃巾道，收掠死獄中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-078-41', 'p0119', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '而讓等實多與張角交通。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-078-42', 'p0119', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '今黨人更為國用，汝曹反與張角通，為可斬未？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-081-43', 'p0119', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '會張角作亂，栩上便宜，頗譏刺左右，不欲國家興兵，但遣將於河上北向讀孝經，賊自當消滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-102-44', 'p0119', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '」其後黃巾賊張角燒州郡，朝廷遣將討平，斬首十餘萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-103-45', 'p0119', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」是後張角作亂稱黃巾，遂破壞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-107-46', 'p0119', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」到中平元年二月，張角兄弟起兵兾州，自號黃天，三十六方，四面出和，將帥星布，吏士外屬，因其疲餧，牽而勝之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-107-47', 'p0119', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '其後張角稱黃天作亂，竟破壞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-107-48', 'p0119', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」袁山松曰：「案張角一時狡亂，不足致此大妖，斯乃曹氏滅漢之徵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-107-49', 'p0119', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '中平元年，黃巾賊張角等立三十六方，起兵燒郡國，山東七州處處應角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-112-50', 'p0119', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '光和末，張角亂，此鄉守險助國，漢嘉之，故立縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a03-118-51', 'p0119', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '張角懷挾妖偽，遐邇搖蕩，八州并發，煙炎絳天，牧守梟裂，流血成川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a04-008-52', 'p0119', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '九州春秋曰：張角之反也，黑山、白波、黃龍、左校、牛角、五鹿、羝根、苦蝤、劉石、平漢、大洪、司隷、緣城、羅市、雷公、浮雲、飛燕、白爵、楊鳳、于毒等各起兵，大者二三萬，小者不減數千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a04-008-53', 'p0119', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '光和中，東方有張角，漢中有張脩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a04-022-54', 'p0119', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '張角起，以植為北中郎將征角，失利抵罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0119-a04-046-55', 'p0119', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '中平元年，黃巾賊帥張角起於魏郡，託有神靈，遣八使以善道教化天下，而潛相連結，自稱黃天泰平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0121-a04-051-0', 'p0121', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '輕財能施，善於交結，與諸葛瑾至厚，委廬江劉靖以得失，江夏李允以衆事，廣陵吳碩、河南張梁以軍旅，而傾心親待，莫不自盡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0121-a04-051-1', 'p0121', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '在事一年，遵皎舊迹，禮劉靖、李允、吳碩、張梁及江夏閭舉等，並納其善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0121-a04-051-2', 'p0121', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '黃武五年，權攻石陽，奐以地主，使所部將軍鮮于丹帥五千人先斷淮道，自帥吳碩、張梁五千人為軍前鋒，降高城，得三將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0121-a04-051-3', 'p0121', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '吳碩、張梁皆裨將軍，賜爵關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0121-a04-058-4', 'p0121', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '軍到白圍，託言住獵，潛遣將軍周峻、張梁等擊江夏新市、安陸、石陽，石陽市盛，峻等奄至，人皆捐物入城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0122-a04-035-0', 'p0122', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '聞孟獲者，為夷、漢所服，募生致之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0122-a04-039-1', 'p0122', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」亮納其策，赦孟獲以服南方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-048-0', 'p0123', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '故魯肅一面而自託，士燮蒙險而效命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-049-1', 'p0123', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '士燮字威彥，蒼梧廣信人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-049-2', 'p0123', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '士燮作守南越，優游終世，至子不慎，自貽凶咎，蓋庸才玩富貴而恃阻險，使之然也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-052-3', 'p0123', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '士燮兄弟，相率供命，南土之賔，自此始也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-053-4', 'p0123', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '士燮旣附孫權，召綜為五官中郎，除合浦、交阯太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-053-5', 'p0123', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '交阯太守士燮遣兵致討，卒不能克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a04-060-6', 'p0123', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '交阯太守士燮卒，權以燮子徽為安遠將軍，領九真太守，以校尉陳時代燮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0123-a05-015-7', 'p0123', 'jinshu', 'a05-015', '《晉書·卷十五》', '建安八年，張津為刺史，士燮為交阯太守，共表立為州，乃拜津為交州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-0', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '郭汜自為車騎將軍，楊定為後將軍，楊奉為興義將軍，董承為安集將軍，並侍送乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-1', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」楊奉、董承引白波帥胡才、李樂、韓暹及匈奴左賢王去卑，率師奉迎，與李傕等戰，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-2', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月，韓暹攻衞將軍董承。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-3', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '封衞將軍董承為輔國將軍伏完等十三人為列侯，贈沮儁為弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-4', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」衞將軍董承為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-5', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '五年春正月，車騎將軍董承、偏將軍王服、越騎校尉种輯受密詔誅曹操，事洩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-009-6', 'p0125', 'houhanshu', 'a03-009', '《後漢書·卷九》', '壬午，曹操殺董承等，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-010b-full-7', 'p0125', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」后手持縑數匹，董承使符節令孫徽以刃脅奪之，殺傍侍者，血濺后衣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-010b-full-8', 'p0125', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '董承女為貴人，操誅承而求貴人殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-010b-9', 'p0125', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '」〉后手持縑數匹，董承使符節令孫徽以刃脅奪之，殺傍侍者，血濺后衣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-010b-10', 'p0125', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '董承女爲貴人，操誅承而求貴人殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-064-11', 'p0125', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '興平元年，詔書徵歧，會帝當還洛陽，先遣衞將軍董承修理宮室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-070-12', 'p0125', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '獻帝春秋，董承之誅，伏后與父完書，言司空殺董承，帝方為報怨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-13', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '又以故牛輔部曲董承為安集將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-14', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '』董承、楊定言曰：『郭汜今且將七百騎來入煨營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-15', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '而張濟與楊奉、董承不相平，乃反合傕、汜，共追乘輿，大戰於弘農東澗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-16', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董承、李樂擁衞左右，胡才、楊奉、韓暹、去卑為後距。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-17', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '爭赴舡者，不可禁制，董承以戈擊披之，斷手指於舟中者可掬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-18', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊彪、董承及后父執金吾伏完等數十人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-19', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '建安元年春，諸將爭權，韓暹遂攻董承，承奔張楊，楊乃使承先繕修洛宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-20', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '干亂政事，董承患之，潛召兖州牧曹操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-21', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '於是封衞將軍董承、輔國將軍伏完等十餘人為列侯，贈沮儁為弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-22', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '封衞將軍董承、輔國將軍伏完、侍中丁沖、种輯、尚書僕射鍾繇、尚書郭溥、御史中丞董芬、彭城相劉艾、馮翊韓斌、東郡太守楊衆、議郎羅邵、伏德、趙蕤為列侯，賞有功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-23', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」以董承為車騎將軍，開府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a03-072-24', 'p0125', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '帝忌操專偪，乃密詔董承，使結天下義士共誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-001-25', 'p0125', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖將迎天子，諸將或疑，荀彧、程昱勸之，乃遣曹洪將兵西迎，衞將軍董承與袁術將萇奴拒險，洪不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-001-26', 'p0125', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '備之未東也，陰與董承等謀反，至下邳，遂殺徐州刺史車胄，舉兵屯沛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-001-27', 'p0125', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '五年春正月，董承等謀泄，皆伏誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-001-28', 'p0125', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '十一月，漢皇后伏氏坐昔與父故屯騎校尉完書，云帝以董承被誅怨恨公，辭甚醜惡，發聞，后廢黜死，兄弟皆伏法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-006-29', 'p0125', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '汜走南山，奉及將軍董承以天子還洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-006-30', 'p0125', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '天子步行趨河岸，岸高不得下，董承等謀欲以馬羈相續以繫帝腰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-008-31', 'p0125', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '建安元年，楊奉、董承、韓暹挾天子還舊京，糧乏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-010-32', 'p0125', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」　獻帝春秋曰：董承之誅，伏后與父完書，言司空殺董承，帝方為報怨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-014-33', 'p0125', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '會天子還洛陽，韓暹、楊奉、董承及楊各違戾不和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-017-34', 'p0125', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '及到洛陽，韓暹、董承日爭鬬，晃說奉令歸太祖；奉欲從之，後悔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-032-35', 'p0125', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主未出時，獻帝舅車騎將軍董承臣松之按：董承，漢靈帝母董太后之姪，於獻帝為丈人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-032-36', 'p0125', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '覩其機兆，赫然憤發，與車騎將軍董承同謀誅操，將安國家，克寧舊都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-032-37', 'p0125', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣昔與車騎將軍董承圖謀討操，機事不密，承見陷害，臣播越失據，忠義不果。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-036-38', 'p0125', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '」　臣松之以為備後與董承等結謀，但事泄不克諧耳，若為國家惜曹公，其如此言何！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0125-a04-046-39', 'p0125', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：策被詔勑，與司空曹公、衞將軍董承、益州牧劉璋等并力討袁術、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0126-a03-010b-full-0', 'p0126', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '安思閻皇后　順烈梁皇后　孝崇匽皇后　桓帝懿獻梁皇后　孝桓鄧皇后　桓思竇皇后　孝仁董皇后　孝靈宋皇后　靈思何皇后　獻帝伏皇后　獻穆曹皇后');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0126-a03-010b-full-1', 'p0126', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '獻帝伏皇后諱壽，琅邪東武人，東武，今密州諸城縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0126-a03-010b-full-2', 'p0126', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '及伏皇后被弒，明年，立節為皇后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0126-a03-010b-3', 'p0126', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '獻帝伏皇后諱壽，琅邪東武人，〈東武，今密州諸城縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-009-0', 'p0127', 'houhanshu', 'a03-009', '《後漢書·卷九》', '山陽公載記曰：「劉備在蜀聞之，遂發喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-009-1', 'p0127', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三輔決錄曰：「時有京兆全禕，字德偉，自以代為漢臣，乃發憤，與耿紀、韋晃欲挾天子以攻魏，南援劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-009-2', 'p0127', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月庚子，劉備自稱漢中王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-009-3', 'p0127', 'houhanshu', 'a03-009', '《後漢書·卷九》', '明年，劉備稱帝于蜀，孫權亦自王於吳，於是天下遂三分矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-054-4', 'p0127', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '及操自平漢中，欲因討劉備而不得進，欲守之又難為功，護軍不知進止何依。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-056-5', 'p0127', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '後許汜與劉備並在荊州牧劉表坐，備共論天下人，汜曰：「陳元龍淮海之士，豪氣不除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-070-6', 'p0127', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '融逼急，乃遣東萊太史慈求救於平原相劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-070-7', 'p0127', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」慈單步見融，旣而求救於劉備，得兵以解圍焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-070-8', 'p0127', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '備驚曰：「孔北海乃復知天下有劉備邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-070-9', 'p0127', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '在郡六年，劉備表領青州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-072-10', 'p0127', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '明年，左將軍劉備誘奉斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-072-11', 'p0127', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '承遂與劉備同謀，未發，會備出征，承更與偏將軍王服、長水校尉种輯、議郎吳碩結謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-074-12', 'p0127', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '五年，左將軍劉備殺徐州刺史車胄，據沛以背曹操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-074-13', 'p0127', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '操今東擊劉備，兵連未可卒解，今舉軍而襲其後，可一往而定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-074-14', 'p0127', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '田豐以旣失前幾，不宜便行，諫紹曰：「曹操旣破劉備，則許下非復空虛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-074-15', 'p0127', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹使劉備、文醜挑戰，曹操又擊破之，斬文醜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-16', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '松懷恨而還，勸璋絕曹氏，而結好劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-17', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '十六年，璋聞曹操當遣兵向漢中討張魯，內懷恐懼，松復說璋迎劉備以拒操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-18', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '』」「劉備有梟名，梟即驍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-19', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '公孫瓚使劉備與術合謀共逼紹，紹與曹操會擊，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-20', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術因欲北至青州從袁譚，曹操使劉備徼之，不得過，復走還壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-21', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '二年閒，操復盡收諸城，破布於鉅野，布東奔劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-22', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '時劉備領徐州，居下邳，與袁術相拒於淮上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-23', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術生年以來，不聞天下有劉備，備乃舉兵與術對戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-24', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '諸將謂布曰：「將軍常欲殺劉備，今可假手於術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-25', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '建安二年，布遂復從袁術，遣順攻劉備於沛，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-075-26', 'p0127', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」顧謂劉備曰：「玄德，卿為坐上客，我為降虜，繩縛我急，獨不可一言邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-105-27', 'p0127', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '曹操略荊州，逐劉備於當陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-105-28', 'p0127', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '十六年，劉備入蜀，與吳再爭荊州，於時戰爭四分五裂之地，荊州為劇，故山鳴之異作其域也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-112-29', 'p0127', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '孱陵魏氏春秋曰：「劉備在荊州所都，改曰公安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a03-113-30', 'p0127', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '建安二十二年，劉備以為郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-31', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術與紹有隙，術求援於公孫瓚，瓚使劉備屯高唐，單經屯平原，陶謙屯發干，以逼紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-32', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '還過郯，謙將曹豹與劉備屯郯東，要太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-33', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '布東奔劉備，張邈從布，使其弟超將家屬保雍丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-34', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱說公曰：「觀劉備有雄才而甚得衆心，終不為人下，不如早圖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-35', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」呂布復為袁術使高順攻劉備，公遣夏侯惇救之，不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-36', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '布之破劉備也，霸等悉從布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-37', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '術欲從下邳北過，公遣劉備、朱靈要之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-38', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '程昱、郭嘉聞公遣備，言於公曰：「劉備不可縱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-39', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」公曰：「夫劉備，人傑也，今不擊，必為後患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-40', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '孫盛魏氏春秋云：荅諸將曰：「劉備，人傑也，將生憂寡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-41', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」紹騎將文醜與劉備將五六千騎前後至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-42', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '紹使劉備助辟，公使曹仁擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-43', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '紹之未破也，使劉備略汝南，汝南賊共都等應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-44', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '今深入征之，劉備必說劉表以襲許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-45', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '八月，表卒，其子琮代，屯襄陽，劉備屯樊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-46', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '軍旣得出，公大喜，諸將問之，公曰：「劉備，吾儔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-47', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '孫盛異同評曰：案吳志，劉備先破公軍，然後權攻合肥，而此記云權先攻合肥，後有赤壁之事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-48', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備襲劉璋，取益州，遂據巴中；遣張郃擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-49', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備遣張飛、馬超、吳蘭等屯下辯；遣曹洪拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-50', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '邈字文然，穆字思然，以禕慷慨有日磾之風，又與王必善，因以閒之，若殺必，欲挾天子以攻魏，南援劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-51', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」秋七月，治兵，遂西征劉備，九月，至長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-001-52', 'p0127', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏侯淵與劉備戰於陽平，為備所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-002-53', 'p0127', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '後密與臣議策質，國人不協，或欲西通，魯即怒曰：『寧為魏公奴，不為劉備上客也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-002-54', 'p0127', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '」魏書曰：癸亥，孫權上書，說：「劉備支黨四萬人，馬二三千匹，出秭歸，請往埽撲，以克捷為效。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-002-55', 'p0127', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '閏月，孫權破劉備於夷陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-003-56', 'p0127', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '又王近出，乘小輦，執達手，撫其背戲之曰：「卿得無為劉備刺客邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-003-57', 'p0127', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '魏略載帝露布天下并班告益州曰：「劉備背恩，自竄巴蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-003-58', 'p0127', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '及劉備走小沛，張飛隨之，過謂宜祿曰：「人取汝妻，而為之長，何蚩蚩若是邪！');
